import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Share links","description":"","frontmatter":{"title":"Share links","lang":"en-US"},"headers":[],"relativePath":"share-links.md","filePath":"share-links.md","lastUpdated":1788554519000}'),r={name:"share-links.md"};function o(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="share-links" tabindex="-1">Share links <a class="header-anchor" href="#share-links" aria-label="Permalink to &quot;Share links&quot;">​</a></h1><p>A share link is a read-only URL for one execution or one failure cluster that anyone can open — no dashboard account, no login. It is the live counterpart of an <a href="./offline-export.html">offline export</a>: instead of a file frozen at export time, the link renders the investigation as it stands when it is opened.</p><p>Share links are <strong>off by default</strong>. Set <code>PIWI_SHARE_LINKS_ENABLED=true</code> to allow them — see the <a href="./configuration.html#authentication">configuration reference</a>.</p><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs without a server, so it has no share links and hides the <strong>Share</strong> button.</p><h2 id="creating-a-link" tabindex="-1">Creating a link <a class="header-anchor" href="#creating-a-link" aria-label="Permalink to &quot;Creating a link&quot;">​</a></h2><p>On an execution page or a failure-cluster page, open <strong>Share</strong> (next to <strong>Export</strong>):</p><ol><li>Pick an expiry. The dialog offers lifetimes up to <code>PIWI_SHARE_LINK_MAX_TTL_DAYS</code> (30 days unless configured; setting it to <code>0</code> lifts the cap and allows links with no expiry).</li><li><strong>Copy the link immediately — it is shown only once.</strong> The server stores a hash of the token, not the token, so there is no way to display the URL again later. Mint a new link instead.</li></ol><p>Creating and revoking links requires the administrator or reporter role; any project member can see which links exist. Each entry in the dialog shows the link&#39;s prefix, its expiry state, and how many times it was opened.</p><h2 id="what-the-viewer-sees" tabindex="-1">What the viewer sees <a class="header-anchor" href="#what-the-viewer-sees" aria-label="Permalink to &quot;What the viewer sees&quot;">​</a></h2><p>The link serves the same self-contained HTML report the <a href="./offline-export.html">offline export</a> produces, rebuilt from the current data on every view — a diagnosis added after the link was minted shows up, a cluster marked fixed reads as fixed. The same size budgets apply (<code>PIWI_EXPORT_MAX_*</code>), so an anonymous view can never cost the server more than an authenticated export does.</p><p>Two consequences of &quot;live&quot; worth knowing:</p><ul><li><strong>Retention thins a shared cluster over time.</strong> When <a href="./storage.html#data-retention">data retention</a> prunes old runs, a cluster link keeps resolving but progressively loses member evidence — the same thinning the dashboard shows. A link whose entity is pruned entirely answers 404. When the investigation must outlive retention, hand over an export file instead.</li><li><strong>Revocation is immediate.</strong> A revoked link stops resolving on the next request. Turning the feature off entirely (<code>PIWI_SHARE_LINKS_ENABLED</code> unset) dead-ends every outstanding link at once without deleting anything, so the variable doubles as a kill switch.</li></ul><h2 id="security-properties" tabindex="-1">Security properties <a class="header-anchor" href="#security-properties" aria-label="Permalink to &quot;Security properties&quot;">​</a></h2><ul><li>The token is a 256-bit random secret (<code>psl_</code> + 64 hex characters) — unguessable at any request rate. The server stores only its SHA-256 hash.</li><li>Everything a link serves is data its creator could already see: minting requires project access, so a link is a narrower delegation of an existing member&#39;s read access, never an escalation.</li><li>The rendered page is sandboxed into a unique origin and served with <code>noindex</code> and <code>Referrer-Policy: no-referrer</code>, so it cannot read dashboard cookies, call the API with credentials, or leak the URL through outbound links. Share responses are never cached.</li><li>A share URL is a capability: anyone holding it can view the page, and it can end up in browser history or proxy logs like any URL. Prefer short expiries, and revoke links when an investigation closes.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./offline-export.html">Offline export</a> — the file to hand over when the recipient has no network path to your instance</li><li><a href="./authentication.html">Authentication</a> — roles, and who can mint or revoke</li><li><a href="./storage.html#data-retention">Storage configuration</a> — retention, and how it interacts with long-lived links</li></ul>',16)])])}const f=t(r,[["render",o]]);export{p as __pageData,f as default};
